python3 << 'EOF'
import re

# Read the main file
with open('/app/resources/treasury_bulletin_1969_10.txt', errors='replace') as f:
    content = f.read()

# Find ALL unique January entries with total outstanding in 300000-400000 range
# Pattern: | YEAR-January | TOTAL | where TOTAL is around 350000-400000
lines = content.split('\n')
year_totals = {}

for i, line in enumerate(lines):
    # Look for lines that have pattern: | YEAR-January | 3XXXXXX |
    # Total outstanding should be around 350000-450000 (millions of dollars)
    if 'January' in line and line.startswith('|'):
        parts = [p.strip() for p in line.split('|') if p.strip()]
        if len(parts) >= 2:
            try:
                val = parts[1].replace(',', '')
                # Check if it's a valid number in the debt range
                if val.isdigit() and 300000 <= int(val) <= 500000:
                    # Extract year
                    year_match = re.search(r'(\d{4})-January', line)
                    if year_match:
                        year = int(year_match.group(1))
                        if 1969 <= year <= 1980:
                            year_totals[year] = int(val)
            except:
                pass

# Print sorted
for year in sorted(year_totals.keys()):
    print(f"January {year}: {year_totals[year]}")
EOF
